changeSet.sql:
-- Rename existing table ALTER TABLE trades RENAME TO trades_legacy;
-- Create partitioned parent table CREATE TABLE trades ( id BIGSERIAL, trade_ref VARCHAR(30) NOT NULL, instrument_id BIGINT NOT NULL REFERENCES instruments(id), counterparty_id BIGINT NOT NULL REFERENCES counterparties(id), asset_class VARCHAR(20) NOT NULL, side VARCHAR(4) NOT NULL, quantity NUMERIC(18,4) NOT NULL, price NUMERIC(18,4) NOT NULL, trade_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', deleted_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, modified_at TIMESTAMP,
PRIMARY KEY (id, trade_date) ) PARTITION BY RANGE (trade_date);
-- Parent indexes CREATE INDEX idx_trades_status ON trades(status);
CREATE INDEX idx_trades_instrument ON trades(instrument_id);
CREATE INDEX idx_trades_counterparty ON trades(counterparty_id);
-- Monthly partitions
CREATE TABLE trades_y2026m04 PARTITION OF trades FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE trades_y2026m05 PARTITION OF trades FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE trades_y2026m06 PARTITION OF trades FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE trades_y2026m07 PARTITION OF trades FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
-- Catch-all partition
CREATE TABLE trades_default PARTITION OF trades DEFAULT;
-- Copy existing data
INSERT INTO trades SELECT * FROM trades_legacy;

rollback.sql:
DROP TABLE IF EXISTS trades CASCADE;

ALTER TABLE trades_legacy
RENAME TO trades;
